  // Help centre and live demo

  'demo.bar.tag': 'دمو',
  'demo.bar.opening': 'در حال باز کردن دموی Curahold',
  'demo.bar.step.db': 'Postgres در همین زبانه راه می‌افتد. هیچ داده‌ای از مرورگرت بیرون نمی‌رود.',
  'demo.bar.step.schema': 'جدول‌ها و قواعد دسترسی ساخته می‌شوند.',
  'demo.bar.step.data': 'یک سبد مشتری ساختگی بارگذاری می‌شود.',
  'demo.bar.step.app': 'برنامه باز می‌شود.',
  'demo.bar.failed': 'دمو باز نشد. صفحه را تازه کن و دوباره امتحان کن.',
  'demo.bar.stuck': 'ورود به دمو انجام نشد.',
  'demo.bar.note': 'داده‌های ساختگی که کاملاً در همین زبانه اجرا می‌شوند. تازه کردن صفحه همه چیز را از نو شروع می‌کند.',
  'demo.bar.as': 'مشاهده به‌عنوان',
  'demo.bar.language': 'زبان دمو',
  'demo.bar.tries': 'چه چیزی را امتحان کنم؟',
  'demo.bar.tours': 'همه تورها',
  'demo.bar.reset': 'از نو شروع کن',
  'demo.bar.customer': 'مشتری · پورتال {company}',
  'demo.idea.1': 'کلید N را بزن و بنویس: «تماس تمدید با Acme friday @مریم #ولتو !high». تاریخ، شخص، مشتری و اولویت خودشان پر می‌شوند؛ اگر چند خط بچسبانی، هر خط یک وظیفه جدا می‌شود.',
  'demo.idea.2': 'در «وظایف من» روی دایره کنار یک وظیفه کلیک کن تا انجام شود. از اعلان پایین صفحه برگردانش.',
  'demo.idea.3': 'مشتریان ← همه مشتریان: نمای «کارت‌ها» نشان می‌دهد چه کسی به توجه نیاز دارد و چرا. نماهای «تمدیدها» و «محصولات» را هم ببین.',
  'demo.idea.4': 'مشتریان ← فرصت‌ها: یک معامله را به مرحله دیگری بکش یا روی «برنده‌شده» رها کن؛ پیش‌بینی بالای صفحه فوراً تغییر می‌کند.',
  'demo.idea.5': 'بینش‌ها ← گزارش‌ها: با «گزارش جدید» گزارش خودت را بساز یا یک گزارش آماده را باز کن و تغییرش بده. بینش‌ها ← داشبوردها: «افزودن» یک داشبورد آماده را به صفحه خانه‌ات می‌آورد.',
  'demo.idea.6': 'بینش‌ها ← تیم: چه کسی چه باری دارد، چه چیزی عقب افتاده و نمای جلسه دونفره برای هر نفر. کار ← خط زمانی هفته‌های پیش رو را نشان می‌دهد.',
  'demo.idea.7': 'مشتریان ← بازبینی‌های کسب‌وکار: بازبینی چه کسی عقب افتاده یا نزدیک است. «انجام شد» یک بازبینی را ثبت می‌کند و تاریخ بعدی را جلو می‌برد. ریتم در تنظیمات ← اهداف و ریتم تعیین می‌شود.',
  'demo.idea.8': 'یک وظیفه را در برد «موفقیت مشتری — عمومی» باز کن: دنبال کردن، پیوند یک وظیفه («منتظر»)، زمان صرف‌شده، چک‌لیست و در پایین تاریخچه. فیلتر و نماها را هم در برد امتحان کن.',
  'demo.idea.9': 'در صفحه هر مشتری، «اعمال یک پلی‌بوک» وظایف شروع کار را با یک کلیک اضافه می‌کند.',
  'demo.idea.10': 'یک وظیفه یا مشتری را حذف کن، بعد از اعلان پایین «واگرد» را بزن یا سطل زباله را از منوی خودت باز کن. هر چه حذف شود ۳۰ روز می‌ماند و با همه زیرمجموعه‌هایش برمی‌گردد.',
  'demo.idea.11': 'CuraAI در پایین سمت چپ: با زبان خودت بپرس (مثلاً «چطور مشتری‌ها را وارد کنم؟»). پاسخ از مستندات می‌آید، همراه با منبعش.',
  'demo.idea.12': 'تنظیمات ← CRMها و صفحه‌گسترده‌ها: یک CRM وصل کن. یک CRM آزمایشی با داده‌های ساختگی مراحل واقعی را طی می‌کند: اجازه دادن، انتخاب آنچه منتقل شود، تطبیق فیلدها و شروع اولین همگام‌سازی.',
  'demo.idea.13': 'یک مشتری را باز کن (مثلاً حمل‌ونقل ولتو): در خط زمانی‌اش یک تماس ثبت کن و «چرا؟» کنار امتیاز سلامت را ببین.',
  'demo.idea.14': 'تنظیمات ← امتیاز سلامت: وزن‌ها را تغییر بده؛ پیش‌نمایش امتیاز هر مشتری را فوراً نشان می‌دهد.',
  'demo.idea.15': 'Ctrl K (یا ⌘ K در Mac) هر مشتری، وظیفه، شخص یا تنظیمی را پیدا می‌کند.',
  'demo.idea.16': 'چند وظیفه را در یک برد انتخاب کن، همه را با هم تغییر بده و بعد واگرد کن.',
  'demo.idea.17': 'تنظیمات ← نقش‌ها و دسترسی‌ها: «مشاهده به‌عنوان …» صفحه‌ها را از چشم یکی از اعضا نشان می‌دهد.',
  'demo.idea.18': 'از بالا به مریم احمدی یا الهام موسوی تغییر کن و ببین در همان صفحه‌ها چه چیزی عوض می‌شود.',
  'demo.idea.19': 'از بالا به نازنین کاظمی (مشتری) تغییر کن: در پورتال کوئیل‌فیلد فقط چیزهایی را می‌بیند که با او به اشتراک گذاشته شده. یک درخواست باز کن و پاسخ بنویس؛ بعد به‌عنوان مریم آن را در برد «موفقیت مشتری — عمومی» باز کن و «پاسخ به مشتری» را بزن.',
  'demo.idea.20': 'منوی تو در پایین سمت چپ: «ظاهر» برای حالت تیره، «زبان» و «میانبرهای صفحه‌کلید» (یا کلید ?).',
